#include "projectile/trail_store.hpp"
namespace projectile { void TrailStore::update(const std::vector<Track>& ts){for(const auto& t:ts){auto& tr=trails_[t.id];tr.push_back({t.center,!t.predicted});while(tr.size()>max_length_)tr.pop_front();}}const Trail* TrailStore::get(int id)const{auto i=trails_.find(id);return i==trails_.end()?nullptr:&i->second;}std::vector<cv::Point2f> TrailStore::observed(int id)const{std::vector<cv::Point2f> r;if(auto t=get(id))for(auto& p:*t)if(p.observed)r.push_back(p.point);return r;}void TrailStore::prune(const std::vector<Track>& ts){std::unordered_map<int,bool> active;for(auto&t:ts)active[t.id]=true;for(auto i=trails_.begin();i!=trails_.end();)if(!active[i->first])i=trails_.erase(i);else ++i;} }
